// ══════════════════════════════════════════════════════
// PARSER — Détecter GED_CALLBACK (clic bouton) ou IGNORER
// ══════════════════════════════════════════════════════
const body = $input.first().json.body || $input.first().json;

if (body.callback_query) {
  const cb = body.callback_query;
  return [{
    json: {
      type:            'GED_CALLBACK',
      chatId:          String(cb.message.chat.id),
      callbackQueryId: cb.id,
      data:            cb.data,
      originalMsgId:   cb.message.message_id
    }
  }];
}

// Ignorer messages texte et autres updates
return [];

// ══════════════════════════════════════════════════════
// PARSER — Extraire choix bouton
// Format callback_data: CAT|CHOIX|FILE_ID
// ══════════════════════════════════════════════════════
const d = $input.first().json;
const parts = (d.data || '').split('|');

if (parts.length < 3 || parts[0] !== 'CAT') {
  throw new Error('callback_data invalide: ' + d.data);
}

const choix = parts[1];
const fileId = parts[2];

return [{
  json: {
    ...d,
    choix:   choix,
    fileId:  fileId,
    ignorer: choix === 'IGNORER'
  }
}];

// Trouver la ligne Staging correspondant au fileId du bouton cliqué
const fileId  = $('🔍 Parser Choix Bouton').first().json.fileId;
const rows    = $input.all();

const match = rows.find(r =>
  String(r.json.File_Id || r.json.fileId || r.json.FileId || '').trim() === String(fileId).trim()
);

if (!match) throw new Error('Ligne Staging introuvable pour fileId: ' + fileId);

return [match];

// ══════════════════════════════════════════════════════
// FUSIONNER — Catégorie choisie + données Staging (v2)
// Nomenclature Zone A→E unifiée v8
// ══════════════════════════════════════════════════════
const cbData  = $('🔍 Parser Choix Bouton').first().json;
const staging = $input.first().json;
const cat     = cbData.choix;

const FISCAL_CATS = ['PRO','AUTONOME','MAISON_BUREAU','PRIV_SANTE','PRIV_AUTO','MIXTE'];
const isFiscal    = FISCAL_CATS.includes(cat);

let fiscalYear = new Date().getFullYear();
try { if (staging.Date) fiscalYear = new Date(staging.Date).getFullYear(); } catch(e) {}

const targetFolderName = isFiscal ? `Impôts ${fiscalYear}` : '_GED_ARCHIVE';

function san(s, max=30) {
  if (!s && s !== 0) return 'INCONNU';
  return String(s).toUpperCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .replace(/[^A-Z0-9]/g,'_').replace(/_{2,}/g,'_')
    .replace(/^_+|_+$/g,'').substring(0, max);
}

const date    = staging.Date || new Date().toISOString().split('T')[0];
const emet    = san(staging.Emetteur, 25);
const objet   = san(staging.Objet || staging.Sous_Categorie, 25);
const benef   = san(staging.Beneficiaire, 20);
const montant = String(staging.Montant_TTC || 0).replace('.','-');

const finalFileName = [date, san(cat,20), emet, objet, benef, montant].join('-') + '.pdf';

return [{
  json: {
    // Identifiants
    fileId:           cbData.fileId,
    chatId:           cbData.chatId,
    originalFileId:   staging.File_Id || staging.fileId || cbData.fileId,
    // Données document — Zone A
    Date:             date,
    Emetteur:         staging.Emetteur      || '',
    Type_Document:    staging.Type_Document || 'ADMIN',
    Beneficiaire:     staging.Beneficiaire  || '',
    Objet:            staging.Objet         || '',
    // Zone B
    Categorie:        cat,
    Sous_Categorie:   staging.Sous_Categorie   || '',
    Confiance:        staging.Confiance        || '',
    Raison_Doute:     staging.Raison_Doute     || '',
    Mention_Manuscrite: staging.Mention_Manuscrite || '',
    // Zone C
    Montant_TTC:          staging.Montant_TTC          || 0,
    Est_Financier:        staging.Est_Financier         ?? true,
    Flag_Mixte:           staging.Flag_Mixte            || false,
    Montant_Pro_Estime:   staging.Montant_Pro_Estime    ?? '',
    Montant_Perso_Estime: staging.Montant_Perso_Estime  ?? '',
    Ratio_Pro_Pct:        staging.Ratio_Pro_Pct         ?? '',
    // Zone D
    Est_Valide_Mixte:   cat === 'MIXTE' ? 'OUI' : '',
    Montant_Pro_Valide: staging.Montant_Pro_Valide || '',
    // Zone E
    Source:    staging.Source   || 'DIRECT_TELEGRAM',
    File_Name: staging.File_Name || '',
    Lien_Drive: '',
    Empreinte: staging.Empreinte || '',
    Hash:      staging.Hash      || '',
    Gmail_Id:  staging.Gmail_Id  || '',
    File_Id:   staging.File_Id   || cbData.fileId || '',
    // Calculs workflow
    finalCategorie:   cat,
    finalFileName:    finalFileName,
    isFiscal:         isFiscal,
    fiscalYear:       fiscalYear,
    targetFolderName: targetFolderName,
    impotsParentId:   $env.GED_IMPOTS_PARENT_ID,
    archiveFolderId:  $env.GED_ARCHIVE_FOLDER_ID
  }
}];

const mergeData = $('🔗 Fusionner Catégorie + Staging').first().json;

let folderId = null;

try {
  const c = $('📁 Créer Dossier').first().json;
  if (c.id) folderId = c.id;
} catch(e) {}

if (!folderId) {
  try {
    const f = $('🔍 Chercher Dossier Cible').first().json;
    if (f.files && f.files.length > 0) folderId = f.files[0].id;
  } catch(e) {}
}

if (!folderId) {
  folderId = mergeData.isFiscal
    ? mergeData.impotsParentId
    : mergeData.archiveFolderId;
}

return [{ json: { ...mergeData, resolvedFolderId: folderId } }];

const d     = $('📌 Résoudre ID Dossier').first().json;
const drive = $('☁️ Upload Renommé').first().json;
const lien  = drive.webViewLink || drive.webContentLink || '';
return [{ json: { ...d, Lien_Drive: lien, jLien: lien } }];
